["event"] = "GTFO",
["use_count"] = false,
["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ...\n        if subEvent == \"SPELL_AURA_REMOVED\"\n        and spellID == 473066 then\n            C_Timer.After(0.2, function() WeakAuras.ScanEvents(\"CAUSESE_DEATH_CHECK\", destGUID) end)\n        elseif subEvent == \"UNIT_DIED\" then\n            --need to exclude bombshells that were killed by rolling over them\n            local npcID = select(6, strsplit(\"-\", destGUID)) \n            if npcID == \"231531\" then\n                aura_env.died[destGUID] = true\n            end\n        end\n    elseif event == \"CAUSESE_DEATH_CHECK\" and ... then\n        local guid = ...\n        if aura_env.died and not aura_env.died[guid] then\n            allstates[guid] = {\n                show = true,\n                changed = true,\n                progressType = \"timed\",\n                duration = 2,\n                expirationTime = 2 + GetTime(),\n                autoHide = true\n            }\n            aura_env.died[guid] = nil\n            return true\n        end\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.died = {}\n    end\nend",
