["custom"] = "function(allstates, event, unit, _, spellID)    \n    if event == \"UNIT_TARGET\" then\n        local _,_,_,_,expirationTime,_,_,_,spellId = UnitCastingInfo(unit)\n        local guid = UnitGUID(unit)\n        if spellId\n        and (spellId == 291928 or spellId == 292264)\n        and guid\n        and not allstates[guid] then\n            allstates[guid] = {\n                show = true,\n                changed =  true,\n                progressType = \"timed\", \n                duration = expirationTime / 1000 - GetTime(),\n                expirationTime = expirationTime / 1000,\n                unit = unit..\"target\",\n                unitIsMe = UnitGUID(unit..\"target\") == WeakAuras.myGUID,\n                autoHide = true,\n            }\n            return true\n        end\n    end\n    if event == \"UNIT_SPELLCAST_STOP\"\n    and (spellID == 291928 or spellID == 292264) then\n        local guid = UnitGUID(unit)\n        if guid then\n            local state = allstates[guid]\n            if state then\n                state.show = false\n                state.changed = true\n                return true\n            end\n        end\n    end\nend",
