["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID = ...\n        if subEvent == \"SPELL_AURA_APPLIED\" and spellID == 466248 then\n            local state = allstates[\"\"]\n            if state then\n                state.stacks = state.stacks + 1\n                state.changed = true\n                return true\n            else\n                allstates[\"\"] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = 15,\n                    expirationTime = 15 + GetTime(),\n                    stacks = 1,\n                    autoHide = true\n                }\n                return true\n            end\n            \n        elseif subEvent == \"SPELL_AURA_REMOVED\" and spellID == 466248 then\n            local state = allstates[\"\"]\n            if state then\n                state.stacks = state.stacks - 1\n                if state.stacks <= 0 then\n                    state.show = false\n                end\n                state.changed = true\n                return true\n            end\n        end\n    end\nend",
