["custom"] = "function(allstates, event, ...)\n    --for some reason BW count doesnt work\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n        if subEvent == \"SPELL_CAST_SUCCESS\" and spellID == 1218488 then\n            local state = allstates[\"\"]\n            if state then\n                state.count = state.count + 1\n                state.changed = true\n                return true\n            end\n        elseif subEvent == \"SPELL_AURA_APPLIED\" and spellID == 1226891 then\n            allstates[\"\"] = {\n                show = true,\n                changed = true,\n                count = 0,\n            }\n            return true\n        end\n    end\nend",
