["useExactSpellId"] = true,
["group_count"] = "0",
["custom"] = "function(allstates, event, ...)\n    local keystoneLevel = C_ChallengeMode.GetActiveKeystoneInfo()\n    if aura_env.config.showAlways or (keystoneLevel and keystoneLevel > 12) then\n        if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n            local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n            if subEvent == \"SPELL_CAST_SUCCESS\"\n            and spellID == 323107\n            and aura_env.timers then\n                aura_env.timers[sourceGUID] = GetTime()\n                allstates[sourceGUID] = {\n                    show = true,\n                    changed = true,\n                    progressType = \"timed\",\n                    duration = 6,\n                    expirationTime = 6 + GetTime(),\n                }\n                return true\n            elseif subEvent == \"UNIT_DIED\" then\n                local state = allstates[destGUID]\n                if state then\n                    state.show = false\n                    state.changed = true\n                    return true\n                end\n            end\n        elseif event == \"ENCOUNTER_START\" then\n            aura_env.timers = {}\n        end\n    end\nend",
