["custom"] = "function(allstates, event, ...)\n    if event == \"COMBAT_LOG_EVENT_UNFILTERED\" then\n        local timestamp, subEvent, hideCaster, sourceGUID, sourceName, sourceFlags, sourceRaidFlags, destGUID, destName, destFlags, destRaidFlags, spellID, _,_, auraType = ...\n        if subEvent == \"SPELL_CAST_START\"\n        and spellID == 320069 then\n            for k,v in pairs(allstates) do \n                v.show = false\n                v.changed = true\n            end\n            aura_env.counter = aura_env.counter + 1\n            local timer = aura_env.timers[aura_env.counter] or 17\n            C_Timer.After(timer-4, function() WeakAuras.ScanEvents(\"CAUSESE_MS_DELAY\", \"nil\") end)\n            return true\n        end\n    elseif event == \"CAUSESE_MS_DELAY\" and ... then\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 4,\n            expirationTime = 4 + GetTime(),\n            autoHide = true,\n        }\n        return true\n    elseif event == \"ENCOUNTER_START\" then\n        aura_env.counter = 0\n        allstates[\"\"] = {\n            show = true,\n            changed = true,\n            progressType = \"timed\",\n            duration = 3.4,\n            expirationTime = 3.4 + GetTime(),\n            autoHide = true,\n        }\n        return true\n    end\nend",
