},
["custom"] = "function(allstates, event, widgetInfo)\n    if event == \"UPDATE_UI_WIDGET\" and next(widgetInfo) then\n        local widgetID = widgetInfo.widgetID\n        if widgetID then\n            local barInfo = C_UIWidgetManager.GetStatusBarWidgetVisualizationInfo(6701)\n            if barInfo then\n                local state = allstates[\"ball\"]\n                if state then\n                    if barInfo.barValue > 100 and state.total == 100 then\n                        state.total = 200\n                        state.value = barInfo.barValue\n                        state.type = 2\n                    else\n                        state.value = barInfo.barValue\n                    end\n                    state.changed = true\n                    return true\n                else\n                    allstates[\"ball\"] = {\n                        show = true,\n                        changed = true,\n                        progressType = \"static\",\n                        value = barInfo.barValue or 0,\n                        total = 100,\n                        type = 1,\n                    }\n                    return true\n                end\n            end\n        end\n    elseif event == \"UNIT_EXITING_VEHICLE\" and widgetInfo then\n        for k,v in pairs(allstates) do\n            v.show = false\n            v.changed = true\n        end\n        return true\n    end\nend",
