},
["finish"] = {
["custom"] = "",
["do_custom"] = false,
},
["init"] = {
["custom"] = "--categoryNumber can be used to differentiate between casts in the conditions for coloring etc\n--role can be (ALL/DAMAGER/HEALER/TANK/MELEE/RANGE) and only shows the bar to that role\n\n--[spellID] = {\"name\",category,\"soundFile\",\"role\", \"show target\" (true/false), \"important\" (true/false)},\naura_env.spellIDs = {\n    --spellIDs moved to CauseseDB\n    \n    [460173] = {\"Repair\",0,\"Kick.ogg\",\"ALL\",false,true}, --Repair\n    \n    \n    \n}\n\n-- this is only for spells where the mobs cast it for roleplay purposes and they should only show if target is in party\naura_env.rpspellIDs = {\n}\n\n--[[\ndefault logic:\n- category 0 is for important interruptible casts\n- category 1 is for interruptible casts\n- category 2 is for ccable and not interruptible casts\n]]\n\naura_env.getCastInfo = function(unit)\n    local name, startC, endC, icon, notInterruptible, spellID, duration, expirationTime, _, castType\n    if UnitCastingInfo(unit) then\n        name, _, icon, startC, endC, _, _, notInterruptible, spellID = UnitCastingInfo(unit)\n        castType = \"cast\"\n    elseif UnitChannelInfo(unit) then\n        name, _, icon, startC, endC, _, notInterruptible, spellID = UnitChannelInfo(unit)\n        castType = \"channel\"\n    end\n    if startC and endC then\n        duration = (endC - startC) / 1000\n        expirationTime = endC / 1000\n    end\n    return name, duration, expirationTime, icon, notInterruptible, spellID, castType\nend",
["do_custom"] = true,
},
},
